    if (type === 'receding') return 'Receding (Dash)';
    if (type === 'comingOut') return 'Coming Out (Wedge)';
    return 'None';
}

function create2DHitTarget(p1, p2, type) {
    const mesh = createCylinderBetween(p1, p2, 0.3, new THREE.MeshBasicMaterial({ visible: false }));
    draw2D.add(mesh);
    registerInteractive(mesh, {
        title: `${getHighlightLabel(type)}`,
        body: `Click to highlight this bond type.`,
        onClick: () => {
            const sel = document.getElementById('highlightBond');
            sel.value = getHighlightLabel(type);
            sel.dispatchEvent(new Event('change'));
        }
    });
}
create2DHitTarget(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 1.3, 0), 'inPlane');
create2DHitTarget(new THREE.Vector3(0, 0, 0), new THREE.Vector3(1.3, -0.4, 0), 'inPlane');
create2DHitTarget(new THREE.Vector3(0, 0, 0), new THREE.Vector3(-1.3, -0.2, 0), 'receding');
create2DHitTarget(new THREE.Vector3(0, 0, 0), new THREE.Vector3(-0.2, -1.4, 0), 'comingOut');

// Leader Arrows
function addLeaderArrow(from, to, text, offset) {
    if (text) createLabel(text, from, true, { fontSize: '12px', offset });
    const dir = to.clone().sub(from).normalize();
    const len = from.distanceTo(to) - 0.1;
    const arrow = new THREE.ArrowHelper(dir, from, len, 0x000000, 0.2, 0.15);
    chemGroup.add(arrow);
}

addLeaderArrow(pDraw2D.clone().add(new THREE.Vector3(1.2, 1.4, 0)), pDraw2D.clone().add(new THREE.Vector3(0.1, 0.7, 0)), 'Bonds in plane<br>of page', [40, -10]);
addLeaderArrow(pDraw2D.clone().add(new THREE.Vector3(1.2, 1.4, 0)), pDraw2D.clone().add(new THREE.Vector3(0.6, 0.0, 0)), '', [0, 0]);
addLeaderArrow(pDraw2D.clone().add(new THREE.Vector3(-1.2, 0.7, 0)), pDraw2D.clone().add(new THREE.Vector3(-0.6, -0.05, 0)), 'Bond receding<br>into page', [-50, -10]);
addLeaderArrow(pDraw2D.clone().add(new THREE.Vector3(1.0, -1.0, 0)), pDraw2D.clone().add(new THREE.Vector3(-0.1, -0.7, 0)), 'Bond coming<br>out of plane', [50, 20]);

// Bottom Bracket & Label
const braceGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-6, -2.2, 0), new THREE.Vector3(-6, -2.4, 0),
    new THREE.Vector3(-0.2, -2.4, 0), new THREE.Vector3(0, -2.7, 0),
    new THREE.Vector3(0.2, -2.4, 0), new THREE.Vector3(6, -2.4, 0),
    new THREE.Vector3(6, -2.2, 0)
]);
chemGroup.add(new THREE.Line(braceGeo, matBlackLine));
createLabel('<b>A tetrahedral carbon atom</b>', new THREE.Vector3(0, -3.2, 0), true, { fontSize: '15px' });

// 2b. 3D Model
const model3DPivot = new THREE.Group();
model3DPivot.position.x = 3.5;
chemGroup.add(model3DPivot);

const model3D = new THREE.Group();
model3DPivot.add(model3D);

const cMesh = new THREE.Mesh(new THREE.SphereGeometry(0.3, 32, 32), matC);
model3D.add(cMesh);

function addAtom3D(pos, type) {
    const hMesh = new THREE.Mesh(new THREE.SphereGeometry(0.2, 32, 32), matH);
    hMesh.position.copy(pos);
    model3D.add(hMesh);
    const rod = createCylinderBetween(new THREE.Vector3(0, 0, 0), pos, 0.06, matRod);
    model3D.add(rod);

    objects[type].spheres3D.push(hMesh);
    objects[type].rods3D.push(rod);

    const intInfo = {
        title: `${getHighlightLabel(type)} (3D)`,
        body: `Click to highlight this bond type.`,
        onClick: () => {
            const sel = document.getElementById('highlightBond');
            sel.value = getHighlightLabel(type);
            sel.dispatchEvent(new Event('change'));
        }
    };
    registerInteractive(hMesh, intInfo);
    registerInteractive(rod, intInfo);
}

addAtom3D(v0, 'inPlane');
addAtom3D(v1, 'inPlane');
addAtom3D(v2, 'receding');
addAtom3D(v3, 'comingOut');

// ==========================================
// Interaction Logic
// ==========================================
let currentView = 'Chemical Notation';

function setView(view) {
    currentView = view;
    const isChem = (view === 'Chemical Notation');
    geoGroup.visible = !isChem;
    chemGroup.visible = isChem;

    allChemLabels.forEach(l => l.div.style.opacity = isChem ? '1' : '0');
    allGeoLabels.forEach(l => l.div.style.opacity = !isChem ? '1' : '0');

    if (isChem) {
        controls.enableRotate = false;
        controls.enablePan = false;
        setCameraView({ projection: 'perspective', azimuthDeg: 0, elevationDeg: 0, rollDeg: 0, heightFraction: 0.6 });
    } else {
        controls.enableRotate = true;
        controls.enablePan = true;
    }
}

function applyHighlight(type) {
    ['inPlane', 'receding', 'comingOut'].forEach(t => {
        objects[t].lines2D.forEach(l => {
            if (l.userData.isWedge) l.material = matBlackPoly;
            else if (l.type === 'Line' && l.geometry === recedingGeo) l.material = matBlackDash;
            else l.material = matBlackLine;
        });
        objects[t].rods3D.forEach(r => r.material = matRod);
        objects[t].spheres3D.forEach(s => s.material = matH);
        objects[t].text2D.forEach(lbl => {
            lbl.div.style.color = '#111';
            lbl.div.style.textShadow = '0 1px 2px #fff';
        });
    });

    if (type !== 'None' && objects[type]) {
        const hlLine = type === 'receding' ? matHighlightDash : matHighlightLine;
        objects[type].lines2D.forEach(l => {
            if (l.userData.isWedge) l.material = matHighlight;
            else l.material = hlLine;
        });
        objects[type].rods3D.forEach(r => r.material = matHighlight);
        objects[type].spheres3D.forEach(s => s.material = matHighlight);
        objects[type].text2D.forEach(lbl => {
            lbl.div.style.color = '#00cccc';
            lbl.div.style.textShadow = '0 0 4px #00ffff, 0 1px 2px #fff';
        });
    }
}

// UI Event Listeners
document.getElementById('panelView').addEventListener('change', (e) => {
    setView(e.target.value);
});

document.getElementById('highlightBond').addEventListener('change', (e) => {
    const val = e.target.value;
    let type = 'None';
    if (val.includes('In Plane')) type = 'inPlane';
    if (val.includes('Receding')) type = 'receding';
    if (val.includes('Coming Out')) type = 'comingOut';
    applyHighlight(type);
});

// Custom 3D Model Rotation
let isDraggingModel = false;
let lastMouseX = 0, lastMouseY = 0;

canvas.addEventListener('pointerdown', (e) => {
    if (currentView !== 'Chemical Notation') return;
    isDraggingModel = true;
    lastMouseX = e.clientX;
    lastMouseY = e.clientY;
});
window.addEventListener('pointerup', () => { isDraggingModel = false; });
canvas.addEventListener('pointermove', (e) => {
    if (!isDraggingModel || currentView !== 'Chemical Notation') return;
    const dx = e.clientX - lastMouseX;
    const dy = e.clientY - lastMouseY;
    lastMouseX = e.clientX;
    lastMouseY = e.clientY;

    const q = new THREE.Quaternion();
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), dx * 0.01);
    model3DPivot.quaternion.premultiply(q);
    q.setFromAxisAngle(new THREE.Vector3(1, 0, 0), dy * 0.01);
    model3DPivot.quaternion.premultiply(q);
});

// Expose demo API
window.goToStep = function (step) {
    const s = step.state;
    if (s.panelView) {
        const el = document.getElementById('panelView');
        if (el.value !== s.panelView) { el.value = s.panelView; el.dispatchEvent(new Event('change')); }
    }
    if (s.highlightBond) {
        const el = document.getElementById('highlightBond');
        if (el.value !== s.highlightBond) { el.value = s.highlightBond; el.dispatchEvent(new Event('change')); }
    }
};

// Initial Setup
setView('Chemical Notation');
applyHighlight('None');

// Final view alignment
setCameraView({ projection: 'perspective', azimuthDeg: 0, elevationDeg: 0, rollDeg: 0, heightFraction: 0.6 });
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

