<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// 1. Scene Setup & Lighting
scene.add(new THREE.AmbientLight(0xffffff, 0.7));
const dirLight = new THREE.DirectionalLight(0xffffff, 0.6);
dirLight.position.set(2, 5, 5);
scene.add(dirLight);

// 2. Materials
const matMagenta = new THREE.MeshBasicMaterial({ color: 0xd900d9 });
const matBlackLine = new THREE.LineBasicMaterial({ color: 0x000000 });
const matBlackDash = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.1, gapSize: 0.1 });
const matBlackWedge = new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide });

const matCyanLine = new THREE.LineBasicMaterial({ color: 0x00cccc });
const matCyanDash = new THREE.LineDashedMaterial({ color: 0x00cccc, dashSize: 0.1, gapSize: 0.1 });
const matCyanWedge = new THREE.MeshBasicMaterial({ color: 0x00cccc, side: THREE.DoubleSide });
const matCyan3D = new THREE.MeshStandardMaterial({ color: 0x00ffff, emissive: 0x006666, roughness: 0.3 });

const matC = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.4 });
const matH = new THREE.MeshStandardMaterial({ color: 0xdddddd, roughness: 0.4 });
const matRod = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, roughness: 0.5 });
const invMat = new THREE.MeshBasicMaterial({ opacity: 0, transparent: true, depthWrite: false });

// 3. Geometry Helpers
function getShortenedSegment(p1, p2, gap1, gap2) {
    const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
    const start = new THREE.Vector3().copy(p1).addScaledVector(dir, gap1);
    const end = new THREE.Vector3().copy(p2).addScaledVector(dir, -gap2);
    return { start, end };
}

function createDashedLine(pStart, pEnd, mat) {
    const geo = new THREE.BufferGeometry().setFromPoints([pStart, pEnd]);
    const line = new THREE.Line(geo, mat);
    line.computeLineDistances();
    return line;
}

function createConeWedge(pStart, pEnd, mat) {
    const dist = pStart.distanceTo(pEnd);
    const coneGeo = new THREE.ConeGeometry(0.12, dist, 16);
    coneGeo.rotateX(Math.PI / 2);
    coneGeo.translate(0, 0, dist / 2);
    const mesh = new THREE.Mesh(coneGeo, mat);
    mesh.position.copy(pStart);
    mesh.lookAt(pEnd);
    return mesh;
}

function create2DWedge(pStart, pEnd, mat) {
    const dir = new THREE.Vector3().subVectors(pEnd, pStart);
    dir.normalize();
    const perp = new THREE.Vector3(-dir.y, dir.x, 0).normalize().multiplyScalar(0.08); // half width of base

    const p1 = new THREE.Vector3().copy(pStart); // narrow tip at Carbon
    const p2 = new THREE.Vector3().copy(pEnd).add(perp); // wide base at Hydrogen
    const p3 = new THREE.Vector3().copy(pEnd).sub(perp);

    const geom = new THREE.BufferGeometry().setFromPoints([p1, p2, p3]);
    geom.computeVertexNormals();
    return new THREE.Mesh(geom, mat);
}

function createEdge(p1, p2, color, thickness) {
    const dist = p1.distanceTo(p2);
    const geom = new THREE.CylinderGeometry(thickness, thickness, dist, 8);
    geom.rotateX(Math.PI / 2);
    geom.translate(0, 0, dist / 2);
    const mesh = new THREE.Mesh(geom, new THREE.MeshBasicMaterial({ color: color }));
    mesh.position.copy(p1);
    mesh.lookAt(p2);
    return mesh;
}

// 4. Coordinates
const vC_2d = new THREE.Vector3(0, 0, 0);
const v0_2d = new THREE.Vector3(0, 1.1, 0);
const v1_2d = new THREE.Vector3(1.1, -0.3, 0);
const v2_2d = new THREE.Vector3(-0.9, -0.2, 0);
const v3_2d = new THREE.Vector3(-0.2, -1.1, 0);

const vC_3d = new THREE.Vector3(0, 0, 0);
const v0_3d = new THREE.Vector3(0, 1.2, 0);
const v1_3d = new THREE.Vector3(1.13, -0.4, 0);
const v2_3d = new THREE.Vector3(-0.56, -0.4, -0.98);
const v3_3d = new THREE.Vector3(-0.56, -0.4, 0.98);

// 5. Structure Groups
const tetra1 = new THREE.Group(); tetra1.position.x = -5.0; scene.add(tetra1);
const tetra2 = new THREE.Group(); tetra2.position.x = -2.0; scene.add(tetra2);
const draw2D = new THREE.Group(); draw2D.position.x = 1.5; scene.add(draw2D);
const model3D = new THREE.Group(); model3D.position.x = 5.0; scene.add(model3D);

const groupRot = new THREE.Euler(0.2, -0.35, 0, 'YXZ');
tetra1.rotation.copy(groupRot);
tetra2.rotation.copy(groupRot);
model3D.rotation.copy(groupRot);

// 6. Build Models & Interaction Tracking
const bondData = {
    inPlane: { lines: [], meshes: [], labels: [] },
    receding: { lines: [], meshes: [], labels: [] },
    comingOut: { lines: [], meshes: [], labels: [] }
};

// --- Tetrahedra 1 & 2 ---
const t1_edges = [
    [v0_3d, v1_3d], [v0_3d, v2_3d], [v1_3d, v2_3d], // outline / back
    [v0_3d, v3_3d], [v1_3d, v3_3d], [v2_3d, v3_3d]  // front
];
t1_edges.forEach((edge, i) => {
    const isFront = i >= 3;
    tetra1.add(createEdge(edge[0], edge[1], 0xd900d9, isFront ? 0.04 : 0.015));
    tetra2.add(createEdge(edge[0], edge[1], 0xd900d9, 0.015));
});

const t2_line0 = new THREE.Line(new THREE.BufferGeometry().setFromPoints([vC_3d, v0_3d]), matBlackLine);
const t2_line1 = new THREE.Line(new THREE.BufferGeometry().setFromPoints([vC_3d, v1_3d]), matBlackLine);
const t2_line2 = createDashedLine(vC_3d, v2_3d, matBlackDash);
const t2_line3 = createConeWedge(vC_3d, v3_3d, matBlackWedge);
tetra2.add(t2_line0, t2_line1, t2_line2, t2_line3);

bondData.inPlane.lines.push(t2_line0, t2_line1);
bondData.receding.lines.push(t2_line2);
bondData.comingOut.meshes.push(t2_line3);

// --- 2D Chemical Drawing ---
const b0_2d = getShortenedSegment(vC_2d, v0_2d, 0.25, 0.25);
const b1_2d = getShortenedSegment(vC_2d, v1_2d, 0.25, 0.25);
const b2_2d = getShortenedSegment(vC_2d, v2_2d, 0.25, 0.25);
const b3_2d = getShortenedSegment(vC_2d, v3_2d, 0.25, 0.25);

const line2d_0 = new THREE.Line(new THREE.BufferGeometry().setFromPoints([b0_2d.start, b0_2d.end]), matBlackLine);
const line2d_1 = new THREE.Line(new THREE.BufferGeometry().setFromPoints([b1_2d.start, b1_2d.end]), matBlackLine);
const line2d_2 = createDashedLine(b2_2d.start, b2_2d.end, matBlackDash);
const line2d_3 = create2DWedge(b3_2d.start, b3_2d.end, matBlackWedge);
draw2D.add(line2d_0, line2d_1, line2d_2, line2d_3);

bondData.inPlane.lines.push(line2d_0, line2d_1);
bondData.receding.lines.push(line2d_2);
bondData.comingOut.meshes.push(line2d_3);

const lbl_C = addLabel('C', new THREE.Vector3(1.5, 0, 0), { fontSize: '18px', background: '#fff' });
const lbl_H0 = addLabel('H', new THREE.Vector3(1.5, 0, 0).add(v0_2d), { fontSize: '18px', background: '#fff' });
const lbl_H1 = addLabel('H', new THREE.Vector3(1.5, 0, 0).add(v1_2d), { fontSize: '18px', background: '#fff' });
const lbl_H2 = addLabel('H', new THREE.Vector3(1.5, 0, 0).add(v2_2d), { fontSize: '18px', background: '#fff' });
const lbl_H3 = addLabel('H', new THREE.Vector3(1.5, 0, 0).add(v3_2d), { fontSize: '18px', background: '#fff' });

bondData.inPlane.labels.push(lbl_H0, lbl_H1);
bondData.receding.labels.push(lbl_H2);
bondData.comingOut.labels.push(lbl_H3);

// --- 3D Ball and Stick Model ---
model3D.add(new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), matC));

[v0_3d, v1_3d, v2_3d, v3_3d].forEach((v, idx) => {
    const sphere = new THREE.Mesh(new THREE.SphereGeometry(0.22, 32, 32), matH);
    sphere.position.copy(v);
    model3D.add(sphere);

    const dist = vC_3d.distanceTo(v);
    const rC = 0.35, rH = 0.22;
    const rodLen = dist - rC - rH;

    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, rodLen, 12), matRod);
    const cylGroup = new THREE.Group();
    cylGroup.position.copy(vC_3d);
    cylGroup.lookAt(v);

    cyl.position.set(0, 0, rC + rodLen / 2);
    cyl.rotation.x = Math.PI / 2; 
    cylGroup.add(cyl);
    model3D.add(cylGroup);

    const type = idx < 2 ? 'inPlane' : (idx === 2 ? 'receding' : 'comingOut');
    bondData[type].meshes.push(sphere, cyl);

    const names = ['In Plane (Solid Line)', 'In Plane (Solid Line)', 'Receding (Dashed)', 'Coming Out (Wedge)'];
    registerInteractive(sphere, {
        title: `Bond Type: ${names[idx]}`,
        body: 'Click to highlight all bonds of this type.',
        onClick: () => {
            const sel = document.getElementById('highlightBond');
            sel.value = type;
            sel.dispatchEvent(new Event('change'));
        }
    });
});

// 7. Interactive Invisible Targets for 2D Bonds
function addInvisibleTarget(p1, p2, type, name) {
    const dist = p1.distanceTo(p2);
    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, dist), invMat);
    const group = new THREE.Group();
    group.position.copy(p1);
    group.lookAt(p2);
    cyl.position.set(0, 0, dist / 2);
    cyl.rotation.x = Math.PI / 2;
    group.add(cyl);
    draw2D.add(group);

    registerInteractive(cyl, {
        title: `Bond Type: ${name}`,
        body: 'Click to highlight all bonds of this type.',
        onClick: () => {
            const sel = document.getElementById('highlightBond');
            sel.value = type;
            sel.dispatchEvent(new Event('change'));
        }
    });
}
addInvisibleTarget(vC_2d, v0_2d, 'inPlane', 'In Plane (Solid Line)');
addInvisibleTarget(vC_2d, v1_2d, 'inPlane', 'In Plane (Solid Line)');
addInvisibleTarget(vC_2d, v2_2d, 'receding', 'Receding (Dashed)');
addInvisibleTarget(vC_2d, v3_2d, 'comingOut', 'Coming Out (Wedge)');

// 8. Visual Framing (Brackets, Labels, Arrows)
const braceGeo = new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0.5, -1.7, 0), new THREE.Vector3(0.6, -1.9, 0),
    new THREE.Vector3(3.25, -1.9, 0), new THREE.Vector3(3.35, -2.1, 0),
    new THREE.Vector3(3.45, -1.9, 0), new THREE.Vector3(6.1, -1.9, 0),
    new THREE.Vector3(6.2, -1.7, 0)
]);
scene.add(new THREE.Line(braceGeo, matBlackLine));

addLabel('<b>A tetrahedral<br>carbon atom</b>', new THREE.Vector3(3.35, -2.5, 0), { fontSize: '14px' });
addLabel('<b>A regular<br>tetrahedron</b>', new THREE.Vector3(-3.5, -2.5, 0), { fontSize: '14px' });

function drawLeader(fromX, fromY, toX, toY) {
    const from = new THREE.Vector3(fromX, fromY, 0);
    const to = new THREE.Vector3(toX, toY, 0);
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length() - 0.05;
    scene.add(new THREE.ArrowHelper(dir.normalize(), from, len, 0x000000, 0.2, 0.12));
}

addLabel('Bonds in plane<br>of page', new THREE.Vector3(3.2, 2.0, 0), { fontSize: '13px' });
drawLeader(3.0, 1.7, 1.5, 0.7);
drawLeader(3.0, 1.7, 2.1, -0.2);

addLabel('Bond receding<br>into page', new THREE.Vector3(-0.2, 1.8, 0), { fontSize: '13px' });
drawLeader(0.0, 1.5, 1.0, -0.1);

addLabel('Bond coming<br>out of plane', new THREE.Vector3(3.0, -1.3, 0), { fontSize: '13px' });
drawLeader(2.6, -1.0, 1.4, -0.7);

// 9. Interaction Logic
const defaultMats = new Map();
['inPlane', 'receding', 'comingOut'].forEach(type => {
    bondData[type].lines.forEach(obj => { if (obj.material) defaultMats.set(obj, obj.material); });
    bondData[type].meshes.forEach(obj => { if (obj.material) defaultMats.set(obj, obj.material); });
});

function applyHighlight(type) {
    ['inPlane', 'receding', 'comingOut'].forEach(t => {
        bondData[t].lines.forEach(obj => obj.material = defaultMats.get(obj));
        bondData[t].meshes.forEach(obj => obj.material = defaultMats.get(obj));
        bondData[t].labels.forEach(l => {
            l.div.style.color = '#111';
            l.div.style.textShadow = 'none';
            l.div.style.fontWeight = 'normal';
        });
    });

    if (!type || type === 'None' || !bondData[type]) return;

    bondData[type].lines.forEach(obj => {
        obj.material = obj.material.isLineDashedMaterial ? matCyanDash : matCyanLine;
    });
    bondData[type].meshes.forEach(obj => {
        if (obj.geometry.type === 'ConeGeometry' || obj.geometry.type === 'BufferGeometry') {
            obj.material = matCyanWedge;
        } else {
            obj.material = matCyan3D;
        }
    });
    bondData[type].labels.forEach(l => {
        l.div.style.color = '#00aaaa';
        l.div.style.textShadow = '0 0 4px #00ffff';
        l.div.style.fontWeight = 'bold';
    });
}

document.getElementById('highlightBond').addEventListener('change', (e) => {
    applyHighlight(e.target.value);
});

// Final framing: orthographic layout matching the textbook view
setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, heightFraction: 0.75 });
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

